<template>
  <main class="audit-page"><header><div><h1>Action audit</h1><p>Review key API requests, response status, and duration for security audits and troubleshooting. </p></div><div><el-input v-model="path" clearable placeholder="Filter by API path" @keyup.enter="load"/><el-button @click="load">Search</el-button></div></header><section><el-table :data="rows" v-loading="loading" stripe><el-table-column prop="createdAt" label="Time" width="180"/><el-table-column prop="username" label="User" width="120"/><el-table-column prop="requestMethod" label="Method" width="80"/><el-table-column prop="requestPath" label="API path" min-width="260" show-overflow-tooltip/><el-table-column prop="statusCode" label="Status" width="80"><template #default="{row}"><el-tag :type="row.statusCode<400?'success':'danger'">{{row.statusCode}}</el-tag></template></el-table-column><el-table-column prop="durationMs" label="Duration (ms)" width="100"/><el-table-column prop="clientIp" label="Client IP" width="150"/></el-table><el-pagination v-model:current-page="page" :page-size="size" :total="total" layout="total, prev, pager, next" @current-change="load"/></section></main>
</template>
<script setup>import{onMounted,ref}from'vue';import{getAuditPage}from'@/api/audit';const rows=ref([]),loading=ref(false),path=ref(''),page=ref(1),size=ref(30),total=ref(0);async function load(){loading.value=true;try{const r=await getAuditPage({page:page.value,size:size.value,path:path.value||undefined});rows.value=r.data?.records||[];total.value=r.data?.total||0}finally{loading.value=false}}onMounted(load);</script>
<style scoped>.audit-page{max-width:1400px;margin:0 auto;padding:32px}.audit-page header{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-bottom:18px}.audit-page header>div:last-child{display:flex;gap:8px}.audit-page h1{margin:0 0 6px}.audit-page p{margin:0;color:var(--ink-500)}.audit-page section{padding:18px;background:var(--paper);border:1px solid var(--line);border-radius:16px}.el-pagination{margin-top:16px;justify-content:flex-end}</style>
